import { mkdir, writeFile } from 'node:fs/promises';
import { createTealOrangeLut } from '../../src/app/features/lut/engine/teal-orange.ts';

const lut = createTealOrangeLut();
const destination = new URL('../../public/luts/hollywood-teal-orange.cube', import.meta.url);
const lines = [
  '# HDR Spotlight original creative SDR preset. MIT License.',
  '# Encoded sRGB input and output; no camera Log conversion.',
  '# Output saturation: 110% of the base recipe, limited to the SDR gamut.',
  '# Generated by tooling/luts/generate-teal-orange.mjs. Red changes fastest.',
  `TITLE "${lut.title}"`,
  `LUT_3D_SIZE ${lut.size}`,
  `DOMAIN_MIN ${lut.domainMin.join(' ')}`,
  `DOMAIN_MAX ${lut.domainMax.join(' ')}`,
];
for (let index = 0; index < lut.values.length; index += 3) {
  lines.push([...lut.values.subarray(index, index + 3)].map((value) => value.toFixed(7)).join(' '));
}
await mkdir(new URL('.', destination), { recursive: true });
await writeFile(destination, `${lines.join('\n')}\n`);
console.info(`Generated ${lut.title}: ${lut.size}³ points → ${destination.pathname}`);
